window.CA = {"date": "Wednesday, 08 July 2026", "updated": "2026-07-08 17:59", "updated_label": "08 Jul 2026, 17:59 IST", "items": [{"title": "US Charges Lawrence Bishnoi and Goldy Brar in Hardeep Singh Nijjar Murder Case; FBI Offers $50,000 Reward", "category": "ir", "category_name": "International Relations", "summary": "The United States Department of Justice has filed charges against Lawrence Bishnoi (currently imprisoned in India) and Goldy Brar for allegedly ordering and orchestrating the June 2023 murder of Canadian Sikh separatist leader Hardeep Singh Nijjar in Surrey, British Columbia. The FBI has offered a $50,000 reward for information leading to Goldy Brar's arrest. The US indictment stops short of directly accusing the Indian government, but places these gangsters at the centre of a transnational murder conspiracy. The charges follow Canada's earlier accusations against India over the Nijjar killing, which had severely strained India-Canada diplomatic relations.", "exam_angle": "Critically relevant for GS Paper 2 (International Relations) — India-Canada diplomatic crisis, transnational organised crime, and India-US relations. Also tests understanding of extradition frameworks and Five Eyes intelligence sharing.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Accused: Lawrence Bishnoi (jailed in India) and Goldy Brar", "Victim: Hardeep Singh Nijjar, killed June 2023 in Surrey, Canada", "Charged by: US Department of Justice", "FBI reward: $50,000 for Goldy Brar's arrest"], "source": "The Hindu / Reuters / The Guardian", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "US-Iran Military Strikes Escalate; Trump Declares Ceasefire Deal 'Over', Oil Prices Surge", "category": "ir", "category_name": "International Relations", "summary": "The United States and Iran exchanged military strikes, escalating tensions in the Middle East after a brief ceasefire attempt collapsed. President Donald Trump declared the ceasefire 'a waste of time' and 'over', signalling continued US military engagement. Following Trump's remarks, Brent crude oil prices surged 6.3% to $78.8 per barrel, reflecting global supply risk concerns. Four oil and gas tankers turned back from the Strait of Hormuz after vessel attacks, with Iran reportedly ordering ships to avoid the Omani corridor — a development with direct implications for India's energy security and oil imports.", "exam_angle": "Key for GS Paper 2 (IR) — US foreign policy, Middle East geopolitics, and Strait of Hormuz as a chokepoint. Connects to GS Paper 3 (Energy Security) — India's dependence on Gulf oil imports and vulnerability to West Asian conflicts.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["US and Iran exchanged military strikes; Trump declared ceasefire 'over'", "Brent crude rose 6.3% to $78.8 per barrel", "Four oil/LNG tankers turned back from Strait of Hormuz", "Iran ordered ships to avoid Omani corridor"], "source": "NDTV / Reuters / Moneycontrol", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "PM Modi Visits Prambanan Temple, Unveils India-Indonesia Heritage Plaque; BrahMos Partnership Sealed", "category": "ir", "category_name": "International Relations", "summary": "Prime Minister Narendra Modi visited the 1,000-year-old Prambanan Hindu temple complex in Indonesia during his state visit and unveiled a joint India-Indonesia heritage commemorative plaque, highlighting civilisational links between the two nations. Separately, India and Indonesia officially sealed a BrahMos supersonic cruise missile partnership, marking a significant defence export milestone for India. The BrahMos deal with Indonesia had been in negotiation since 2022 and represents India's growing defence export footprint in Southeast Asia.", "exam_angle": "Relevant for GS Paper 2 (IR) — India's Act East Policy, ASEAN relations, and defence diplomacy. The BrahMos export connects to GS Paper 3 (Defence/Sci-Tech) — indigenisation and defence exports under Atmanirbhar Bharat.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["PM Modi visited Prambanan temple (1,000-year-old Hindu temple, Indonesia) and unveiled India-Indonesia heritage plaque", "India and Indonesia sealed BrahMos supersonic cruise missile partnership", "BrahMos is a joint venture between India's DRDO and Russia's NPO Mashinostroyeniya", "Reflects India's Act East Policy and growing defence exports"], "source": "News18 / The Indian Express", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "PM Modi's Australia Visit: 'Rock Star' Welcome Amid Human Rights Protests", "category": "ir", "category_name": "International Relations", "summary": "Prime Minister Narendra Modi visited Australia as part of his multi-nation tour, receiving a large-scale welcome from the Indian diaspora described as a 'rock star' reception. The visit also witnessed human rights protests related to the Khalistan issue and the Nijjar murder case. Modi's Australia visit is part of broader efforts to strengthen the Comprehensive Strategic Partnership between India and Australia, which covers trade, defence, education, and critical minerals.", "exam_angle": "Relevant for GS Paper 2 (IR) — India-Australia bilateral relations, Quad grouping, and diaspora diplomacy. Context of the Nijjar case protests adds a layer connecting to India-Canada-Australia diplomatic tensions.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["PM Modi visited Australia as part of multi-nation tour", "India-Australia relationship status: Comprehensive Strategic Partnership", "Australia is a member of the Quad alongside India, USA, and Japan", "Visit coincided with human rights protests over Khalistan issue and Nijjar case"], "source": "The Guardian", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Sensex Sinks 1,680 Points, Nifty Closes Below 23,900 Amid US-Iran Escalation and Global Uncertainty", "category": "economy", "category_name": "Economy & Banking", "summary": "Indian equity markets witnessed a sharp selloff on July 8, 2026, with the BSE Sensex falling approximately 1,680 points and Nifty50 closing below 23,900, a drop of nearly 2%. The primary triggers were Trump's declaration that the US-Iran ceasefire was 'over', rising crude oil prices, and broader global risk-off sentiment. The market crash affected energy, banking, and aviation stocks most severely. This reflects the high sensitivity of Indian markets to geopolitical developments in the Middle East given India's oil import dependence.", "exam_angle": "Relevant for GS Paper 3 (Economy) — transmission of global geopolitical shocks to Indian financial markets, imported inflation via crude oil, and India's current account vulnerability.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Sensex fell ~1,680 points on July 8, 2026", "Nifty50 closed below 23,900 (approx. 2% decline)", "Key trigger: US-Iran military escalation and rising crude oil prices", "Brent crude rose 6.3% to $78.8/barrel on the same day"], "source": "The Economic Times / The Times of India", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Russia's Share in India's Oil Imports Crosses 40% in May 2026", "category": "economy", "category_name": "Economy & Banking", "summary": "Russia's share in India's total crude oil imports crossed 40% in May 2026, maintaining its position as India's largest oil supplier even as Indian refiners continue to pay a premium over benchmark prices. This trend, which began after Western sanctions on Russia following the Ukraine invasion in 2022, has reshaped India's oil import basket significantly. The development is occurring against the backdrop of fresh geopolitical tensions in the Middle East, making India's energy diversification strategy critical.", "exam_angle": "Important for GS Paper 3 (Economy/Energy Security) — India's strategic oil sourcing, impact of sanctions on global energy markets, and India's balancing act between Western allies and Russia in energy trade.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Russia's share in India's crude oil imports: >40% in May 2026", "Russia is India's largest single crude oil supplier", "India continues to pay a premium over benchmark prices for Russian oil", "Shift began post-2022 Ukraine invasion and Western sanctions on Russia"], "source": "The Hindu", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "India Urges US to Reconsider Proposed 12.5% Tariff Under USTR Section 301 'Forced Labour' Probe", "category": "economy", "category_name": "Economy & Banking", "summary": "India has formally urged the United States to reconsider a proposed 12.5% additional tariff on Indian goods being considered under USTR's (United States Trade Representative) Section 301 investigation into alleged 'forced labour' practices. This comes amid already stalled India-US bilateral trade deal negotiations. The Section 301 mechanism allows the US to impose trade sanctions in response to practices it deems 'unreasonable or discriminatory'. India's goods exports to the US could be significantly impacted if the tariff is implemented.", "exam_angle": "Key for GS Paper 2 (IR) and GS Paper 3 (Economy) — India-US trade relations, WTO-compatible trade remedy mechanisms, and the broader context of Trump-era tariff policies affecting Indian exports.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["US proposed 12.5% tariff on Indian goods under USTR Section 301", "Reason cited: 'Forced labour' practices", "India has formally requested reconsideration", "Section 301 of US Trade Act allows unilateral tariffs on 'unfair' trade practices"], "source": "The Times of India", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "India-US Trade Deal Remains Stuck Despite Diplomatic Engagement", "category": "economy", "category_name": "Economy & Banking", "summary": "The much-awaited India-US bilateral trade agreement continues to remain stalled, with analysts citing multiple sticking points including US demands on market access for agricultural and dairy products, digital trade norms, and India's data localisation requirements. The ongoing tariff threats under USTR probes have further complicated negotiations. India is the US's largest trading partner in South Asia, and both sides had signalled intent to fast-track a deal.", "exam_angle": "Relevant for GS Paper 2 (IR) and GS Paper 3 (Economy) — India-US trade architecture, protectionism versus liberalisation debate, and India's multilateral and bilateral trade strategy.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["India-US bilateral trade deal negotiations remain deadlocked", "Key sticking points: agricultural market access, digital trade, data localisation", "India is US's largest South Asian trading partner", "Concurrent USTR tariff threats have complicated the negotiations"], "source": "The New Indian Express", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "RBI and Tax Department Back Cryptocurrency Ban; Warn of Tax Evasion Risks", "category": "economy", "category_name": "Economy & Banking", "summary": "Documents reviewed by Reuters reveal that India's central bank (RBI) has backed a blanket ban on cryptocurrencies, while the Income Tax Department has separately warned of significant tax evasion risks posed by crypto assets. The RBI's position reflects concerns about financial stability, monetary policy transmission, and capital flight. India currently taxes crypto gains at 30% with a 1% TDS on transactions, but regulatory clarity on the legal status of cryptocurrencies remains pending.", "exam_angle": "Important for GS Paper 3 (Economy) — RBI's monetary policy powers, cryptocurrency regulation debate in India, and digital asset governance. Links to the Cryptocurrency and Regulation of Official Digital Currency Bill.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["RBI has backed a blanket ban on cryptocurrencies", "Income Tax Department warns of tax evasion through crypto", "India currently taxes crypto gains at 30% + 1% TDS on transactions", "Legal/regulatory status of crypto in India remains unresolved"], "source": "Reuters", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Ethanol-Blend Fuel Backlash Intensifies in India; Carmakers Under Scrutiny", "category": "environment", "category_name": "Environment & Ecology", "summary": "A growing backlash against ethanol-blended fuel (particularly E20 — 20% ethanol blend) is intensifying in India, with consumer complaints about reduced engine performance and mileage, and carmakers facing criticism over inadequate adaptation of vehicle technology. India's National Policy on Biofuels targets 20% ethanol blending in petrol by 2025-26 under the Pradhan Mantri JI-VAN Yojana and the Ethanol Blending Programme (EBP). The controversy raises questions about the pace of implementation versus vehicle fleet readiness.", "exam_angle": "Relevant for GS Paper 3 (Environment/Economy) — India's ethanol blending programme, biofuel policy, energy security, and the Pradhan Mantri JI-VAN Yojana. Also links to reducing import dependence on crude oil.", "gs_paper": "GS Paper 3 (Environment)", "key_facts": ["India targets 20% ethanol blending in petrol (E20) by 2025-26", "Policy instrument: Ethanol Blending Programme (EBP) and PM JI-VAN Yojana", "Consumer backlash: complaints of reduced engine performance and mileage", "Carmakers face scrutiny over inadequate adaptation to E20 fuel standards"], "source": "Reuters", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Wayanad Debris Slip: 5 Missing, Amit Shah Pledges Centre's Support; Environmentalists Demand Halt to Tunnel Works", "category": "environment", "category_name": "Environment & Ecology", "summary": "A fresh debris slip in Wayanad district of Kerala left 5 persons missing, prompting Union Home Minister Amit Shah to pledge full central government support for rescue and relief operations. Environmental groups held the Kerala government accountable and demanded suspension of ongoing tunnel construction works in the ecologically sensitive Western Ghats region. Wayanad has witnessed repeated landslides and debris flows, underscoring the persistent vulnerability of the region to geological hazards, especially during the southwest monsoon season.", "exam_angle": "Key for GS Paper 3 (Environment/Disaster Management) — landslide vulnerability in Western Ghats, NDMA guidelines, and the broader debate over development versus environmental conservation in ecologically sensitive zones (ESZs).", "gs_paper": "GS Paper 3 (Environment)", "key_facts": ["Location: Wayanad district, Kerala (Western Ghats)", "Persons missing after debris slip: 5", "Union Home Minister Amit Shah pledged Centre's support", "Environmentalists demanded suspension of tunnel construction in the region"], "source": "The Hindu", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Supreme Court Questions Centre Over Blanket Ban on Pregnant IPS Officers During Probation Training", "category": "polity", "category_name": "Polity & Governance", "summary": "The Supreme Court of India questioned the Union Government over a policy that imposes a blanket ban on pregnant IPS (Indian Police Service) officers from undergoing probation training, effectively stalling their career progression. The Court raised concerns that such a policy may violate the constitutional rights of women officers under Articles 14 (equality), 16 (equal opportunity in public employment), and 21 (right to life and personal liberty). The case raises significant questions about gender discrimination in India's civil services training framework.", "exam_angle": "Directly relevant for GS Paper 2 (Polity/Governance) — fundamental rights (Articles 14, 16, 21), gender equality in civil services, and judicial review of executive policies. Also connects to the Maternity Benefit Act and gender-sensitive governance.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Issue: Blanket ban on pregnant IPS officers during probation training", "Supreme Court questioned the Union Government on the policy", "Constitutional provisions at stake: Articles 14, 16, and 21", "IPS is an All India Service governed by the IPS (Cadre) Rules"], "source": "NDTV", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Bombay High Court Upholds Woman's Right to Flee Forced Marriage; Invokes Personal Liberty", "category": "polity", "category_name": "Polity & Governance", "summary": "The Bombay High Court protected a woman fleeing a forced marriage, invoking Article 21 (Right to Life and Personal Liberty) and declaring 'Your Life, Your Choice'. The court refused to allow the woman to be returned to her matrimonial home against her will, affirming that individual autonomy and freedom from coercion are fundamental rights under the Constitution. The ruling reinforces a growing body of High Court jurisprudence protecting women's agency in matrimonial matters.", "exam_angle": "Key for GS Paper 2 (Polity) — judicial interpretation of Article 21, fundamental rights, and the right to personal liberty. Connects to gender justice, habeas corpus petitions, and the expanding scope of the right to life.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Court: Bombay High Court", "Constitutional basis: Article 21 (Right to Life and Personal Liberty)", "Ruling: Court protected woman fleeing forced marriage", "Key phrase used by court: 'Your Life, Your Choice'"], "source": "NDTV", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Ram Temple Donation Theft: SIT Report Names Avinash Shukla as Prime Accused; Security Lapses Identified", "category": "polity", "category_name": "Polity & Governance", "summary": "A Special Investigation Team (SIT) report on theft of donations at the Ram Temple in Ayodhya has named Avinash Shukla as the prime accused. The SIT found that temple staff stole cash from donation boxes and that security protocols were not enforced. The report highlights systemic failures in the administration of the Ram Janmabhoomi temple, which was consecrated in January 2024. The Shri Ram Janmabhoomi Teerth Kshetra Trust manages the temple complex.", "exam_angle": "Relevant for GS Paper 2 (Governance) — accountability mechanisms in autonomous trusts, management of religious institutions, and the role of SITs in criminal investigation. The Ram Temple is a landmark institution under a government-formed trust.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["SIT named Avinash Shukla as prime accused in Ram Temple donation theft", "SIT found: staff stole cash, security protocols not enforced", "Managing body: Shri Ram Janmabhoomi Teerth Kshetra Trust", "Ram Temple was consecrated in January 2024 in Ayodhya, Uttar Pradesh"], "source": "Scroll.in / The Hindu", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "NATO Summit: Trump Attacks Spain as 'Terrible Partner', Demands Greenland; Exposes Alliance Cracks", "category": "ir", "category_name": "International Relations", "summary": "At the NATO summit, US President Donald Trump launched a sharp attack on Spain, calling it 'a terrible partner' and threatening to cut off trade, labelling it 'a wasted cause'. Trump simultaneously reiterated demands for control over Greenland, citing its strategic importance for US defence and resource interests amid competition with Russia and China. The summit exposed significant internal divisions within NATO, with Trump questioning the value of collective defence commitments for allies he deems insufficiently compliant.", "exam_angle": "Relevant for GS Paper 2 (IR) — NATO's internal cohesion, US foreign policy under Trump, and Greenland's strategic importance. Connects to Arctic geopolitics and the shifting nature of multilateral alliances.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Trump called Spain 'a terrible partner' and threatened trade cutoff at NATO summit", "Trump reiterated demand for control over Greenland", "Greenland is an autonomous territory of Denmark, strategically located in the Arctic", "Summit exposed cracks in NATO's internal unity"], "source": "The Times of India / Al Jazeera", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Google to Expand AI Data Centres in India; Signals Growing Digital Infrastructure Investment", "category": "scitech", "category_name": "Science & Technology", "summary": "Google's cloud business CEO Thomas Kurian announced that Google will set up more Artificial Intelligence (AI) data centres in India as demand for cloud and AI services grows. This is part of Google's broader global strategy to build AI infrastructure and aligns with India's Digital India and emerging data centre policy framework. The move follows similar announcements by other global tech giants and comes amid India's push to become an AI hub under the IndiaAI Mission.", "exam_angle": "Relevant for GS Paper 3 (Sci-Tech/Economy) — India's digital infrastructure development, IndiaAI Mission, data localisation debate, and India's emergence as a global AI hub. Connects to the National Data Governance Framework.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Google to expand AI data centres in India; announced by Cloud CEO Thomas Kurian", "India is targeting becoming a global AI hub under the IndiaAI Mission", "Government of India has a dedicated Digital India programme and National Data Governance Framework", "Reflects growing FDI in India's digital infrastructure sector"], "source": "Livemint", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "China Considering Restrictions on Overseas Access to Advanced AI Models", "category": "scitech", "category_name": "Science & Technology", "summary": "China is reportedly weighing curbs on overseas access to its advanced Artificial Intelligence models, a move that could further fragment the global AI ecosystem and accelerate the AI technology decoupling between China and Western nations. This development comes amid US restrictions on export of advanced semiconductors to China and growing competition between the two nations in AI development. A global report also warned that AI firms worldwide are lagging on safety measures.", "exam_angle": "Relevant for GS Paper 3 (Sci-Tech) and GS Paper 2 (IR) — AI governance, technology decoupling between US and China, global AI safety norms, and implications for India's AI strategy and tech diplomacy.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["China considering restricting overseas access to its advanced AI models", "Context: Ongoing US-China technology decoupling, US semiconductor export controls", "Separate global report warns AI firms worldwide are lagging on safety measures", "Impacts global AI governance architecture and India's tech partnerships"], "source": "NDTV", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Uttar Pradesh Approves Startup Policy 2026 with Focus on $1 Trillion Economy Target", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "The Uttar Pradesh government under Chief Minister Yogi Adityanath cleared the Startup Policy 2026, aimed at fostering entrepreneurship and innovation in the state with an eye on achieving UP's $1 trillion (₹84 lakh crore) economy goal. The policy is expected to provide incentives including seed funding, incubation support, and regulatory ease for startups. Uttar Pradesh has been aggressively positioning itself as an investment destination following successive Investor Summits.", "exam_angle": "Relevant for GS Paper 3 (Economy) and GS Paper 2 (Governance) — state-level startup ecosystems, economic decentralisation, and the connection between innovation policy and GDP targets. Connects to the national Startup India initiative.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["Policy: Uttar Pradesh Startup Policy 2026", "Approved by: Yogi Adityanath-led UP government", "Target: Support UP's $1 trillion economy goal", "Key features: Seed funding, incubation support, regulatory ease"], "source": "India Today", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "Lashkar-e-Taiba Commander Killed in Shopian Encounter, J&K", "category": "defence", "category_name": "Defence & Security", "summary": "A Lashkar-e-Taiba (LeT) commander who had been trapped in South Kashmir's Shopian district for four days was killed in a security forces encounter. Police confirmed the elimination of the LeT militant, with a search operation continuing for a second militant. The operation is part of ongoing counter-insurgency efforts by the Indian Army, CRPF, and J&K Police in the Kashmir Valley, where LeT remains one of the most active Pakistan-based terrorist organisations.", "exam_angle": "Relevant for GS Paper 3 (Internal Security) — counter-terrorism operations in J&K, Lashkar-e-Taiba's operational presence, and the role of unified command structure in J&K security operations.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Outfit: Lashkar-e-Taiba (LeT), a Pakistan-based terrorist organisation", "Location: Shopian district, South Kashmir", "LeT commander killed after 4-day siege/encounter operation", "Operation involved: Indian Army, J&K Police (unified command)"], "source": "NDTV / The Hindu", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "PM Modi Visits 1,000-Year-Old Prambanan Temple in Indonesia: Cultural Diplomacy and Heritage Linkages", "category": "culture", "category_name": "Art & Culture", "summary": "Prime Minister Narendra Modi visited the Prambanan temple complex in Yogyakarta, Indonesia — a UNESCO World Heritage Site and one of the largest Hindu temple complexes in Southeast Asia, dating back to the 9th-10th century CE. Modi unveiled a joint India-Indonesia heritage plaque, emphasising the deep cultural and civilisational links between the two nations rooted in Hinduism, Sanskrit literature, and the Ramayana tradition. The visit underlines India's use of cultural diplomacy as a tool of soft power in the Indo-Pacific region.", "exam_angle": "Relevant for GS Paper 1 (Culture) — India's cultural links with Southeast Asia, Hindu temple architecture abroad, and UNESCO World Heritage Sites. Also connects to GS Paper 2 (IR) — India's soft power diplomacy and cultural outreach.", "gs_paper": "GS Paper 1 (Culture)", "key_facts": ["Prambanan: UNESCO World Heritage Site, located in Yogyakarta, Indonesia", "Age: ~1,000 years (built circa 9th-10th century CE), dedicated to the Hindu Trimurti", "PM Modi unveiled India-Indonesia joint heritage plaque during visit", "Prambanan reflects Hindu-Buddhist cultural influence in Southeast Asia (Indianisation)"], "source": "News18", "day": "2026-07-08", "day_label": "08 Jul"}, {"title": "India–Indonesia Defence Deal: BrahMos and Astra Missiles to Be Supplied to Indonesia", "category": "defence", "category_name": "Defence & Security", "summary": "India is set to supply BrahMos supersonic cruise missiles and Astra air-to-air missiles to Indonesia, confirmed by an Indian government official during PM Modi's state visit to Jakarta. This marks a significant expansion of India's defence exports under its 'Make in India' and defence export push. The deal is part of a broader strategic partnership being formalised between the two countries. Indonesia becomes one of the key Southeast Asian nations to acquire the BrahMos system, which is jointly developed by India and Russia.", "exam_angle": "Relevant to GS Paper 2 (IR/Defence) — India's defence export ambitions, BrahMos as a strategic product, and deepening ties with ASEAN nations under Act East Policy.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Missiles: BrahMos (supersonic cruise) and Astra (air-to-air)", "BrahMos is a joint venture between India (DRDO/BrahMos Aerospace) and Russia", "Indonesia is an ASEAN nation; deal part of India's Act East Policy", "Announced during PM Modi's state visit to Jakarta (July 2026)"], "source": "Reuters / The Hindu", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "PM Modi Visits Indonesia: IIM Campus, UPI, AI, Critical Minerals and EVM Cooperation Announced", "category": "ir", "category_name": "International Relations", "summary": "PM Narendra Modi visited Jakarta, Indonesia, heralding what he called a 'golden chapter' in India–Indonesia relations. Key announcements included setting up an IIM Bangalore campus in Indonesia, extending UPI payment infrastructure, cooperation on artificial intelligence and critical minerals, and an MoU on election management including export of customised Electronic Voting Machines (EVMs). PM Modi also received Indonesia's highest civilian honour, the 'Bintang Adipurna'. PM Modi highlighted the next 25 years as crucial for the bilateral partnership and the Indian Ocean region.", "exam_angle": "Tests knowledge of India's bilateral diplomacy, Act East Policy, defence/tech exports, and India's soft power through institutions like IIMs. The EVM export MoU is significant for polity questions.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Award received: 'Bintang Adipurna' — Indonesia's highest state honour", "IIM Bangalore to set up campus in Indonesia", "MoU on election management and export of customised EVMs signed", "Cooperation areas: UPI, AI, critical minerals, satellite launch capability, defence"], "source": "The Times of India / News18 / NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "PM Modi Offers Indonesia Satellite Launch Capability; Deepens Space Partnership", "category": "scitech", "category_name": "Science & Technology", "summary": "During PM Modi's visit to Jakarta, India offered Indonesia satellite launch capability as part of deepening the bilateral space partnership. This aligns with ISRO's expanding commercial launch services under NewSpace India Limited (NSIL). The offer reflects India's growing role as a provider of space services to developing and partner nations in the Indo-Pacific region. Space cooperation was among multiple high-tech areas announced during the summit.", "exam_angle": "Links to ISRO's commercial arm NSIL, India's space diplomacy, and the broader theme of India as a space-faring nation offering services to allies.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["India offered satellite launch capability to Indonesia", "ISRO's commercial arm: NewSpace India Limited (NSIL)", "Part of India–Indonesia summit outcomes, July 2026", "Relevant to India's Act East Policy and space diplomacy"], "source": "News18", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "2008 Ahmedabad Serial Blasts Case: Gujarat High Court Upholds Death Penalty for 38 Convicts", "category": "polity", "category_name": "Polity & Governance", "summary": "The Gujarat High Court upheld the death penalty for 38 convicts in the 2008 Ahmedabad serial blasts case, which involved a series of bomb explosions across the city that killed over 56 people and injured hundreds. The government described the verdict as a 'historic victory'. The case involved one of the largest terrorist attacks in India and the trial court had earlier awarded the death sentence to 38 and life imprisonment to others. The High Court confirmation is a necessary step before the matter can go to the Supreme Court.", "exam_angle": "Relevant to criminal law, capital punishment jurisprudence, and constitutional provisions on the right to life (Article 21). Also tests knowledge of India's counter-terrorism legal framework.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Incident: 2008 Ahmedabad serial bomb blasts (56+ killed)", "Court: Gujarat High Court upheld death penalty", "Number of convicts on death row confirmed: 38", "Mandatory confirmation of death sentences by High Court under CrPC before Supreme Court appeal"], "source": "The Hindu", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "E20 Petrol Row: Supreme Court Takes Up Petition; Concerns Over Damage to E10 Vehicles", "category": "environment", "category_name": "Environment & Ecology", "summary": "A report and a Supreme Court petition have raised concerns that E20 petrol (containing 20% ethanol blended with petrol) may damage rubber fuel system components in older vehicles designed for E10 (10% ethanol blend). A litigant before the Supreme Court alleged 'silent compulsion' in the E20 rollout. India is pursuing its ethanol blending programme — achieving 20% blending by 2025–26 — as part of its energy security and climate commitments. Petroleum Minister Hardeep Puri defended the programme, saying car manufacturers are comfortable with the transition.", "exam_angle": "Connects to India's National Biofuel Policy, ethanol blending targets, energy security, and the intersection of environmental policy with consumer rights.", "gs_paper": "GS Paper 3 (Environment)", "key_facts": ["E20 = 20% ethanol blended petrol; E10 = 10% ethanol blend", "India's target: 20% ethanol blending by 2025–26 under National Biofuel Policy 2018", "Concern: E20 may damage rubber parts in E10-compatible vehicles", "Matter raised before the Supreme Court of India"], "source": "Moneycontrol / The Hindu", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Wayanad Landslide: IMD Red Alert, 5 Dead; Kerala Ministers Term It 'Man-Made Disaster'", "category": "environment", "category_name": "Environment & Ecology", "summary": "A landslide struck Wayanad district in Kerala following heavy rainfall, killing at least 5 people and prompting a red alert from the India Meteorological Department (IMD). Two Kerala ministers termed the disaster 'man-made', raising questions about construction activity and deforestation in the ecologically sensitive Western Ghats. Wayanad was the site of a catastrophic landslide in July 2024 as well, making it a region of recurring disaster vulnerability. Simultaneously, the IMD issued red alerts for Delhi and an orange alert for Mumbai as the monsoon intensified across India.", "exam_angle": "Relevant to disaster management, Western Ghats ecology, Gadgil and Kasturirangan Committee recommendations on ecologically sensitive zones, and IMD's alert system.", "gs_paper": "GS Paper 3 (Environment)", "key_facts": ["Location: Wayanad, Kerala — ecologically sensitive part of Western Ghats", "Deaths: At least 5 in the latest landslide", "IMD alert levels: Red (extreme), Orange (very heavy), Yellow (heavy rainfall) — colour-coded system", "Kerala ministers attributed the disaster to human activity ('man-made')"], "source": "The Hindu / NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Strait of Hormuz Tanker Attacks: Three Commercial Ships Hit, Oil Prices Rise", "category": "ir", "category_name": "International Relations", "summary": "The United Kingdom Maritime Trade Operations (UKMTO) reported that three commercial tankers were hit by unidentified projectiles in the Strait of Hormuz, with no casualties reported. Oil prices rose on reports of the attack, which was attributed to Iranian-linked activity by media reports. The Strait of Hormuz is one of the world's most critical oil chokepoints, through which roughly 20% of global oil trade passes. The attacks are part of ongoing escalation in the West Asia/Middle East region.", "exam_angle": "Strait of Hormuz is a critical chokepoint for global energy security and directly impacts India's oil import costs. Relevant to GS Paper 2 (IR) and GS Paper 3 (Economy — energy security).", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Location: Strait of Hormuz — between Iran and Oman", "~20% of global oil trade passes through the Strait of Hormuz", "Reporting authority: UKMTO (UK Maritime Trade Operations)", "Three tankers hit; oil prices rose on news of attacks"], "source": "The Hindu", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Macron Visits Syria: Blast Near Damascus Hotel During French Presidential Visit", "category": "ir", "category_name": "International Relations", "summary": "French President Emmanuel Macron made a state visit to Damascus, Syria — a significant diplomatic visit marking engagement with Syria's new post-Assad government. During the visit, a blast was reported near his hotel, though Macron was unharmed. The visit signalled Western re-engagement with Syria following the fall of Bashar al-Assad's government. France's diplomatic outreach to Syria is part of broader international efforts to stabilise the country and address the refugee and humanitarian crisis.", "exam_angle": "Relevant to GS Paper 2 (IR) — geopolitics of West Asia, France's foreign policy, and Syria's post-conflict political transition.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["French President Macron visited Damascus, Syria", "Blast reported near his hotel during the visit; Macron was unharmed", "Significance: Western diplomatic re-engagement with post-Assad Syria", "Syria's Assad government fell in late 2024 after rebel offensive"], "source": "NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "UNICEF: Over 300 Children Killed or Wounded in Sudan War in Six Months", "category": "ir", "category_name": "International Relations", "summary": "UNICEF reported that over 300 children have been killed or wounded in Sudan's ongoing civil war over a period of six months, highlighting the severe humanitarian toll of the conflict between the Sudanese Armed Forces (SAF) and the Rapid Support Forces (RSF). The Sudan conflict, which began in April 2023, has created one of the world's largest displacement crises. UNICEF's report underscores the violation of international humanitarian law and the targeting of civilian infrastructure in the war.", "exam_angle": "Relevant to GS Paper 2 (IR) — international organisations (UNICEF), humanitarian law, and Africa-related current affairs that frequently appear in UPSC Prelims.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["300+ children killed or wounded in Sudan conflict over 6 months: UNICEF", "Sudan conflict: SAF vs RSF (Rapid Support Forces), began April 2023", "One of the world's largest displacement/humanitarian crises", "UNICEF is a UN agency focused on children's welfare (HQ: New York)"], "source": "NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Trump Considers Selling F-35 Fighter Jets to Turkey", "category": "defence", "category_name": "Defence & Security", "summary": "US President Donald Trump stated that the United States would consider selling F-35 stealth fighter jets to Turkey. Turkey was originally part of the F-35 programme but was removed in 2019 after it purchased Russia's S-400 air defence system, triggering US sanctions under CAATSA (Countering America's Adversaries Through Sanctions Act). Trump's statement signals a possible shift in US policy and a potential easing of tensions with Turkey, a NATO ally. The development is significant for NATO cohesion and US arms export policy.", "exam_angle": "Connects to CAATSA (relevant because India also purchased S-400 from Russia), NATO dynamics, and US arms export policy — all frequent UPSC IR themes.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["F-35 is a 5th-generation stealth multirole fighter (Lockheed Martin)", "Turkey was expelled from F-35 programme in 2019 after S-400 purchase from Russia", "CAATSA (Countering America's Adversaries Through Sanctions Act) was the sanctions basis", "India also purchased S-400 from Russia and faced CAATSA waiver pressure"], "source": "NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Ukraine Strikes 8 Russian 'Shadow Fleet' Tankers Delivering Fuel to Crimea", "category": "ir", "category_name": "International Relations", "summary": "Ukraine conducted strikes on eight Russian 'shadow fleet' tankers that were delivering fuel to Crimea, which Russia annexed in 2014. The 'shadow fleet' refers to vessels used by Russia to circumvent Western oil sanctions imposed after the 2022 invasion of Ukraine. Targeting of these tankers represents Ukraine's strategy to disrupt Russian fuel supply lines, especially to occupied territories. The development has implications for global shipping insurance and maritime security.", "exam_angle": "Relevant to the Russia-Ukraine conflict, Western sanctions architecture, the concept of 'shadow fleets', and energy security — all important for GS Paper 2 IR and GS Paper 3 Economy.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["'Shadow fleet': vessels used to evade Western oil sanctions on Russia", "Crimea was annexed by Russia in 2014; internationally recognised as Ukrainian territory", "Eight tankers struck by Ukraine in this operation", "Western sanctions cap Russian oil at $60/barrel under G7 Price Cap mechanism"], "source": "NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "TribeX Digital Learning Platform for Tribal Arts and Culture Launched by Union Tribal Affairs Minister", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "Union Minister for Tribal Affairs Jual Oram launched 'TribeX', a digital learning platform dedicated to tribal arts, culture, and traditional knowledge. The platform is designed to preserve, promote, and disseminate India's rich tribal heritage in a digital format, making it accessible to tribal communities and the wider public. The launch aligns with the Ministry of Tribal Affairs' mandate to protect tribal identities and livelihoods under constitutional provisions (Articles 15, 16, 46, and the Fifth and Sixth Schedules).", "exam_angle": "Relevant to GS Paper 2 (Schemes/Welfare) — government initiatives for tribal welfare, digital empowerment, and constitutional safeguards for Scheduled Tribes.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Platform name: TribeX", "Launched by: Union Minister Jual Oram, Ministry of Tribal Affairs", "Purpose: Digital learning for tribal arts, culture, and traditional knowledge", "Relevant constitutional provisions: Articles 46, Fifth Schedule, Sixth Schedule (NE India)"], "source": "PIB", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Taj Mahal–Tejo Mahalaya Petition: Allahabad High Court Issues Notice to Centre", "category": "culture", "category_name": "Art & Culture", "summary": "The Allahabad High Court issued a notice to the Central Government on a petition claiming that the Taj Mahal was built on a pre-existing Hindu temple site called 'Tejo Mahalaya'. The petition seeks a court-directed investigation into the historical claims. The Taj Mahal, built by Mughal Emperor Shah Jahan in the 17th century in Agra, is a UNESCO World Heritage Site and one of India's most iconic monuments. Similar petitions in the past have been dismissed by courts.", "exam_angle": "Relevant to heritage/culture questions, Places of Worship (Special Provisions) Act 1991, and constitutional provisions on religious sites — a recurring issue in UPSC current affairs.", "gs_paper": "GS Paper 1 (Culture)", "key_facts": ["Monument: Taj Mahal, Agra — UNESCO World Heritage Site (designated 1983)", "Built by: Mughal Emperor Shah Jahan (17th century) in memory of Mumtaz Mahal", "Petition claims: Taj Mahal built over 'Tejo Mahalaya' Hindu temple site", "Court: Allahabad High Court issued notice to Centre"], "source": "NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "ZEE5 Removes 'Satluj' (Punjab 95) After Government Cites IT Rules and Security Concerns", "category": "polity", "category_name": "Polity & Governance", "summary": "OTT platform ZEE5 removed the film 'Satluj' (based on the Diljit Dosanjh-produced 'Punjab 95', depicting the human rights situation during the 1984–95 Punjab militancy period) after the government cited security concerns and the IT Rules 2021 as grounds for the takedown. The film had previously been held up by the Central Board of Film Certification (CBFC). SGPC and Shiromani Akali Dal condemned the removal. The case raises questions about OTT regulation, freedom of expression, and government powers under the IT (Intermediary Guidelines and Digital Media Ethics Code) Rules 2021.", "exam_angle": "Directly relevant to GS Paper 2 (Polity) — OTT regulation under IT Rules 2021, CBFC's powers, freedom of speech (Article 19(1)(a)), and reasonable restrictions.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Film: 'Satluj' (Punjab 95) — depicts 1984–95 Punjab militancy and human rights issues", "Platform: ZEE5 removed the film citing government direction", "Legal basis cited: IT (Intermediary Guidelines and Digital Media Ethics Code) Rules 2021", "Regulatory body: CBFC (Central Board of Film Certification) had earlier withheld certification"], "source": "The Indian Express", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Pakistan Issues 'War' Threat Over Indus Waters Amid Suspended Treaty", "category": "ir", "category_name": "International Relations", "summary": "Pakistan issued statements threatening war with India over Indus Waters, amid the monsoon season when river flows are high and following India's suspension of the Indus Waters Treaty (IWT) after the Pahalgam terrorist attack in April 2025. India suspended the 1960 Indus Waters Treaty — brokered by the World Bank — as a retaliatory measure. The IWT governs the sharing of six rivers of the Indus system between India and Pakistan, with the western rivers (Indus, Jhelum, Chenab) allocated to Pakistan and eastern rivers (Ravi, Beas, Sutlej) to India.", "exam_angle": "Critical for GS Paper 2 (IR) — Indus Waters Treaty, India–Pakistan relations, water diplomacy, and World Bank's role as a mediator/guarantor.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Indus Waters Treaty (IWT) signed in 1960 — brokered by World Bank", "Western rivers (Indus, Jhelum, Chenab) allocated to Pakistan; Eastern (Ravi, Beas, Sutlej) to India", "India suspended IWT after Pahalgam terror attack (April 2025)", "Pakistan threatened war over Indian actions on Indus water flows"], "source": "NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "Bengaluru Startup's Surveillance Satellite Knocked Out by Solar Activity", "category": "scitech", "category_name": "Science & Technology", "summary": "A surveillance satellite operated by a Bengaluru-based startup was knocked out of service due to intense solar activity (likely a geomagnetic storm or solar flare), with the company vowing to make a comeback. The incident highlights the vulnerability of low-Earth orbit (LEO) satellites to space weather events. India's private space sector has been growing rapidly following the liberalisation of the space sector through the Indian Space Policy 2023 and the establishment of IN-SPACe (Indian National Space Promotion and Authorisation Centre).", "exam_angle": "Relevant to India's private space sector, IN-SPACe, space weather hazards, and the broader theme of space security and satellite vulnerability.", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Incident: Solar activity (geomagnetic storm/solar flare) disabled a surveillance satellite", "Operator: Bengaluru-based private space startup", "Regulatory body for Indian private space sector: IN-SPACe (under DoS)", "Indian Space Policy 2023 opened space sector to private players"], "source": "NDTV", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "India's Semiconductor (Chip) Manufacturing Push Faces Execution Challenges", "category": "economy", "category_name": "Economy & Banking", "summary": "An analysis highlights that India's semiconductor manufacturing ambitions face the biggest challenge not in policy design but in execution — including lack of specialised talent, supply chain gaps, water and power requirements, and delays in facility construction. India has approved semiconductor projects under the India Semiconductor Mission (ISM), including facilities by Tata Electronics (in Dholera, Gujarat) and Micron Technology (ATMP facility in Sanand, Gujarat). The global chip race is intensifying with the US CHIPS Act and EU Chips Act offering competing incentives.", "exam_angle": "Directly relevant to GS Paper 3 (Economy/Sci-Tech) — India Semiconductor Mission, Atmanirbhar Bharat in electronics, and critical technology supply chains.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["India Semiconductor Mission (ISM) launched under MeitY with Rs 76,000 crore incentive package", "Approved projects: Tata Electronics (Dholera, Gujarat) and Micron Technology ATMP (Sanand, Gujarat)", "Key challenge highlighted: Execution — talent, supply chain, infrastructure", "Global context: US CHIPS Act ($52 bn) and EU Chips Act competing for semiconductor investment"], "source": "The Times of India", "day": "2026-07-07", "day_label": "07 Jul"}, {"title": "India-UK Free Trade Agreement Set for July 15 Rollout; Industry Welcomes Pact", "category": "ir", "category_name": "International Relations", "summary": "The India-UK Free Trade Agreement (FTA) is scheduled to come into effect on July 15, 2026, sparking significant industry optimism. The pact covers goods, services, and investment, and is expected to boost bilateral trade substantially. It is one of the most comprehensive trade deals India has signed in recent years, covering sectors including pharmaceuticals, textiles, professional services, and digital trade.", "exam_angle": "India's bilateral trade agreements are a recurring GS Paper 2 (IR) and GS Paper 3 (Economy) topic; aspirants should know key provisions, sectors covered, and strategic significance of the India-UK FTA.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India-UK FTA rollout date: July 15, 2026", "Covers goods, services, investment, and digital trade", "One of India's most comprehensive bilateral trade deals", "Sectors benefiting: pharmaceuticals, textiles, professional services"], "source": "India Today", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "India Lifts Gas Supply Curbs Imposed During Strait of Hormuz Disruption as LNG Supply Resumes", "category": "economy", "category_name": "Economy & Banking", "summary": "India lifted emergency gas supply restrictions that were imposed during a period of disruption to shipping through the Strait of Hormuz. The government confirmed that 15 India-bound ships carrying urea, DAP (diammonium phosphate), and sulphur had successfully crossed the Hormuz Strait. The Hormuz Strait is critical to India's energy security, as a significant share of India's crude oil and LNG imports transit through it. The lifting of curbs signals normalisation of supply chains.", "exam_angle": "The Strait of Hormuz is strategically vital for India's energy imports; this event connects to India's energy security, import dependency, and West Asia geopolitics — all frequent exam themes.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["15 India-bound ships carrying urea, DAP, sulphur crossed Hormuz", "India lifted gas supply curbs imposed during Hormuz disruption", "LNG and fertiliser supply chains now normalised", "Strait of Hormuz: critical chokepoint for India's oil and gas imports"], "source": "The Quint / The Times of India", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "India and Russia Set $50 Billion Bilateral Investment Target by 2030", "category": "ir", "category_name": "International Relations", "summary": "India and Russia have agreed to set a bilateral investment target of $50 billion by 2030, deepening economic engagement between the two countries. This comes amid continued strategic partnership even as Russia faces Western sanctions over the Ukraine conflict. The investment push covers sectors such as energy, defence, fertilisers, and infrastructure. India-Russia trade has surged in recent years, particularly in crude oil imports.", "exam_angle": "India-Russia economic ties, especially amid Western sanctions and India's strategic autonomy doctrine, are highly relevant for GS Paper 2 (IR) and GS Paper 3 (Economy).", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India-Russia bilateral investment target: $50 billion by 2030", "Sectors: energy, defence, fertilisers, infrastructure", "India-Russia trade has expanded significantly due to crude oil imports post-2022", "Russia remains a key defence supplier and strategic partner for India"], "source": "The Economic Times", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "EAM Jaishankar on 4-Nation Diplomatic Tour; Meets Qatar PM on Energy and West Asia", "category": "ir", "category_name": "International Relations", "summary": "External Affairs Minister S. Jaishankar undertook a 4-nation diplomatic tour, which included a meeting with the Prime Minister of Qatar to review bilateral energy ties, trade relations, and the situation in West Asia. Qatar is one of India's largest suppliers of LNG and is home to a large Indian diaspora. The visit comes amid heightened tensions in the region following the death of Iranian Supreme Leader Ali Khamenei.", "exam_angle": "India's West Asia diplomacy, energy security (LNG from Qatar), and diaspora engagement are key GS Paper 2 (IR) topics; EAM Jaishankar's tours frequently appear in current affairs.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["EAM Jaishankar undertook a 4-nation diplomatic tour", "Met Qatar PM to review energy, trade, and West Asia situation", "Qatar is a major LNG supplier to India", "Visit coincides with regional tensions post-Khamenei death"], "source": "India Today", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "Netanyahu Cites India's Support After JD Vance Calls US 'Only Ally' of Israel", "category": "ir", "category_name": "International Relations", "summary": "Israeli Prime Minister Benjamin Netanyahu pushed back against US Vice President JD Vance's claim that the US was Israel's 'only ally,' explicitly citing India and its 1.4 billion people as friends of Israel. This public statement highlights the growing perception of India-Israel strategic closeness even as India has maintained a formal stance supporting the two-state solution. The remark drew significant attention to the nature of India's foreign policy balancing act.", "exam_angle": "India-Israel relations, India's West Asia policy, and India's strategic autonomy (maintaining ties with both Israel and Arab/Palestinian sides) are key GS Paper 2 (IR) themes.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Netanyahu cited India ('1.4 billion Indians') as supporters of Israel", "JD Vance had called the US Israel's 'only ally'", "India officially supports the two-state solution for Palestine", "India-Israel defence and technology ties have deepened since 2017"], "source": "NDTV / News18", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "PM Modi's Indonesia Visit to Focus on UPI, Defence, and Digital Public Infrastructure Partnership", "category": "ir", "category_name": "International Relations", "summary": "Prime Minister Narendra Modi's upcoming visit to Indonesia is set to focus on expanding UPI (Unified Payments Interface) adoption, defence cooperation, and digital public infrastructure (DPI) partnerships. Indonesia is one of the largest economies in Southeast Asia and an important partner in ASEAN. India has been actively promoting its DPI stack — including UPI, Aadhaar, and DigiLocker — as a global model for digital governance.", "exam_angle": "India's Act East Policy, UPI's global expansion, and DPI diplomacy are central to GS Paper 2 (IR) and GS Paper 3 (Sci-Tech/Economy); Indonesia is a key ASEAN partner.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Modi's Indonesia visit agenda: UPI expansion, defence, Digital Public Infrastructure", "Indonesia is a key ASEAN and G20 partner for India", "India's DPI stack (UPI, Aadhaar, DigiLocker) being promoted globally", "UPI now operational in several countries through bilateral MoUs"], "source": "NDTV Profit", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "Trump to Meet Zelensky and Syrian President at NATO Summit in Turkey", "category": "ir", "category_name": "International Relations", "summary": "US President Donald Trump is scheduled to meet Ukrainian President Zelensky and Syria's new President at the upcoming NATO Summit to be held in Turkey. Trump also held a 'businesslike' phone call with Russian President Putin, offering again to facilitate a ceasefire in Ukraine. The NATO summit in Turkey is significant as it brings together key actors in the ongoing conflicts in both Ukraine and West Asia.", "exam_angle": "NATO's evolving role, US-Russia-Ukraine conflict dynamics, and Turkey's strategic positioning within NATO are important GS Paper 2 (IR) themes for Prelims and Mains.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["NATO Summit venue: Turkey", "Trump to meet Zelensky and Syrian President at the summit", "Trump-Putin call described as 'businesslike'; US offered mediation on Ukraine", "Russia claimed it captured Kostiantynivka town; Ukraine disputed the claim"], "source": "NDTV", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "Iran Seeks Tighter Control Over Strait of Hormuz Following Khamenei's Death", "category": "ir", "category_name": "International Relations", "summary": "Following the death of Iranian Supreme Leader Ali Khamenei, Iran has signalled intentions to tighten its control over the Strait of Hormuz, a critical global oil and gas chokepoint. The US reportedly pressured countries to reduce participation at Khamenei's funeral, with at least 13 nations withdrawing or reducing their delegations. Khamenei's son Mojtaba, widely seen as a potential successor, notably skipped the funeral. The post-Khamenei succession dynamics could significantly affect regional stability.", "exam_angle": "The Strait of Hormuz is the world's most critical oil chokepoint; Iran's leadership transition has major implications for India's energy security, West Asia stability, and global oil markets.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["Ali Khamenei was Iran's Supreme Leader; died recently", "Mojtaba Khamenei is considered the likely successor but skipped the funeral", "Strait of Hormuz: ~20% of global oil trade passes through it", "US pressured at least 13 nations to reduce participation at Khamenei's funeral"], "source": "NDTV / The Guardian", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "India's Ethanol Blending (E20) Programme Faces Pushback from Motorists Over Mileage Concerns", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "India's ethanol blending programme — which mandates E20 fuel (20% ethanol blended with petrol) — is facing public resistance from motorists citing reduced fuel efficiency (mileage loss) and engine compatibility concerns. Oil companies and the auto industry have defended the safety and viability of E20, while the government maintains the programme is essential for energy security and reducing carbon emissions. The E20 target is part of India's National Biofuel Policy 2018.", "exam_angle": "India's biofuel/ethanol blending programme is directly linked to energy security, agriculture (sugarcane/maize as feedstock), and climate commitments — a cross-cutting GS Paper 3 topic.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["E20: petrol blended with 20% ethanol; mandated under National Biofuel Policy 2018", "India's ethanol blending target: 20% by 2025-26", "Concerns: reduced mileage, engine compatibility for older vehicles", "Ethanol feedstock: sugarcane, maize, food grain surplus"], "source": "Bloomberg / The Indian Express", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "Centre Cracks Down on Instagram Over Child Sexual Abuse Content; Orders Immediate Ad Suspension", "category": "polity", "category_name": "Polity & Governance", "summary": "The Central Government has issued a stern notice to Instagram, ordering it to immediately stop running advertisements and demanding a response over the platform's failure to curb child sexual abuse material (CSAM) content. The Ministry of Electronics and Information Technology (MeitY) is the nodal authority for regulating digital intermediaries in India under the IT Act 2000 and IT (Intermediary Guidelines and Digital Media Ethics Code) Rules 2021. This action reflects increasing government scrutiny of Big Tech platforms.", "exam_angle": "Digital regulation of social media intermediaries under IT Rules 2021, CSAM as a legal issue, and MeitY's regulatory role are highly relevant for GS Paper 2 (Polity/Governance) and GS Paper 3 (Sci-Tech).", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["Government ordered Instagram to stop ads over CSAM content", "Nodal authority: MeitY (Ministry of Electronics and IT)", "Governing law: IT Act 2000 + IT (Intermediary Guidelines) Rules 2021", "Intermediaries must act on CSAM within 24 hours under IT Rules 2021"], "source": "The Times of India", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "India's Passport Ranking Slips; Remains Outside Top 100 on Global Passport Index", "category": "reports", "category_name": "Reports & Indices", "summary": "India's passport ranking has fallen further, remaining outside the top 100 on the latest global passport power index. The Henley Passport Index ranks passports by the number of visa-free or visa-on-arrival destinations accessible. India's passport provides access to a limited number of countries without prior visa, reflecting the relatively restricted global mobility of Indian passport holders compared to top-ranked nations.", "exam_angle": "Passport indices and India's global standing on such indices are frequently tested in Prelims; connects to bilateral visa agreements, diplomatic relations, and soft power.", "gs_paper": "GS Paper 2 (IR)", "key_facts": ["India's passport ranking: outside top 100 (Henley Passport Index 2026)", "Henley Passport Index ranks by number of visa-free/on-arrival destinations", "Top-ranked passports (2026): typically Singapore, Japan, Germany, France", "India's passport grants visa-free access to approximately 58-62 countries"], "source": "The Times of India", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "Army Corners Two Lashkar-e-Taiba Terrorists in J&K's Shopian; Counter-Terror Operation Underway", "category": "defence", "category_name": "Defence & Security", "summary": "The Indian Army launched a counter-terrorism operation in the Shopian district of Jammu & Kashmir after surveillance cameras detected two local Lashkar-e-Taiba (LeT) militants in an orchard. The Army plugged escape routes and cordoned off the area. Operations in Shopian are part of ongoing counter-insurgency efforts in the Kashmir Valley, where LeT remains one of the most active proscribed terrorist organisations.", "exam_angle": "Counter-terror operations in J&K, Lashkar-e-Taiba's designation as a terrorist organisation, and India's security architecture in J&K are key defence and internal security topics for GS Paper 3.", "gs_paper": "GS Paper 3 (Defence)", "key_facts": ["Location: Shopian district, Jammu & Kashmir", "Group: Lashkar-e-Taiba (LeT) — UN-designated terrorist organisation", "Army used surveillance cameras to detect militants", "LeT is based in Pakistan; banned under UAPA in India"], "source": "The Times of India / NDTV", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "Indian Naval Ships Conclude Successful Visit to Singapore, Deepening Maritime Ties", "category": "defence", "category_name": "Defence & Security", "summary": "Indian Naval ships concluded a successful port visit to Singapore as part of ongoing efforts to strengthen maritime cooperation in the Indo-Pacific region. India and Singapore have robust defence ties, including regular bilateral naval exercises such as SIMBEX (Singapore-India Maritime Bilateral Exercise). Singapore is a key partner in India's Act East Policy and plays an important role in the strategic Malacca Strait region.", "exam_angle": "India's maritime diplomacy, Act East Policy, Indo-Pacific strategy, and India-Singapore defence relations are recurring GS Paper 2 (IR) and GS Paper 3 (Defence) themes.", "gs_paper": "GS Paper 3 (Defence)", "key_facts": ["Indian Naval ships completed a port visit to Singapore", "India-Singapore bilateral naval exercise: SIMBEX (held annually)", "Singapore is a key partner in India's Act East Policy", "Malacca Strait: strategic chokepoint near Singapore critical for India's trade"], "source": "PIB", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "NFDC-NFAI's 4K Restoration of 'Oka Oorie Katha' Makes World Premiere at 60th Karlovy Vary International Film Festival", "category": "culture", "category_name": "Art & Culture", "summary": "The National Film Development Corporation (NFDC) and National Film Archive of India (NFAI) jointly restored the 1977 Telugu classic 'Oka Oorie Katha' (directed by Mrinal Sen) in 4K and premiered it at the 60th Karlovy Vary International Film Festival in the Czech Republic. This is part of India's film heritage preservation initiative. NFAI, under MIB, is responsible for preserving and restoring India's cinematic heritage.", "exam_angle": "Film heritage conservation by NFDC/NFAI and India's cultural diplomacy through film festivals are relevant for GS Paper 1 (Culture) and GS Paper 2 (Governance/Soft Power).", "gs_paper": "GS Paper 1 (Culture)", "key_facts": ["Film: 'Oka Oorie Katha' (1977 Telugu film, dir. Mrinal Sen)", "Restored in 4K by NFDC and NFAI jointly", "World Premiere: 60th Karlovy Vary International Film Festival, Czech Republic", "NFAI (National Film Archive of India) is under Ministry of Information & Broadcasting"], "source": "PIB", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "Meghalaya's South Garo Hills Records Zero Maternal Deaths for Eight Consecutive Months", "category": "schemes", "category_name": "Govt Schemes & Policies", "summary": "South Garo Hills district in Meghalaya has achieved zero maternal deaths for eight consecutive months, a remarkable public health milestone for a region that had historically recorded high maternal mortality. This achievement is attributed to improved institutional deliveries, better ANM (Auxiliary Nurse Midwife) coverage, and effective implementation of centrally sponsored schemes such as Janani Suraksha Yojana (JSY) and the POSHAN Abhiyaan. Meghalaya's MMR had been one of the higher ones among northeastern states.", "exam_angle": "Maternal Mortality Rate (MMR) reduction, Janani Suraksha Yojana, and healthcare delivery in northeastern states are key GS Paper 2 (Governance/Social Justice) topics.", "gs_paper": "GS Paper 2 (Polity)", "key_facts": ["South Garo Hills, Meghalaya: zero maternal deaths for 8 consecutive months", "Key schemes driving this: Janani Suraksha Yojana (JSY), POSHAN Abhiyaan", "India's target MMR: below 70 per lakh live births (SDG target: below 70 by 2030)", "India's national MMR has declined significantly over the past decade"], "source": "NDTV", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "India Needs Second Home for Asiatic Lions: Conservation Experts", "category": "environment", "category_name": "Environment & Ecology", "summary": "Conservation experts and reports have reiterated the urgency of establishing a second home for the Asiatic lion (Panthera leo persica), currently found exclusively in the Gir National Park and Wildlife Sanctuary in Gujarat. The Supreme Court had earlier directed the central government to relocate some lions to Kuno-Palpur National Park in Madhya Pradesh. The single-population vulnerability makes Asiatic lions susceptible to extinction from disease outbreaks or natural disasters.", "exam_angle": "Asiatic lion conservation, Project Lion, Gir National Park, the Supreme Court's Kuno-Palpur relocation order, and biodiversity protection connect to GS Paper 3 (Environment) and GS Paper 2 (Polity/Judiciary).", "gs_paper": "GS Paper 3 (Environment)", "key_facts": ["Asiatic Lion (Panthera leo persica): found only in Gir, Gujarat — IUCN: Endangered", "Supreme Court directed relocation of some lions to Kuno-Palpur NP, Madhya Pradesh", "Current Asiatic lion population: approximately 674 (2020 census)", "Project Lion launched in 2020 to protect and increase lion population"], "source": "The Hindu", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "India's Top IT Firms Face Muted Q1 Results as AI Spending Fails to Translate into Revenue Growth", "category": "economy", "category_name": "Economy & Banking", "summary": "A report projects that India's top IT companies — including TCS, Infosys, Wipro, and HCL Technologies — are set for subdued Q1 FY27 results despite heavy AI-related spending by global clients. The disconnect between AI investment and actual IT services revenue growth reflects a transition period where AI tools are being implemented but have not yet generated large-scale outsourcing contracts. TCS Q1 results are among the key events watched in the week ahead.", "exam_angle": "India's IT sector performance, the impact of AI on outsourcing, and India's services exports are relevant for GS Paper 3 (Economy); IT sector is a major contributor to India's GDP and foreign exchange earnings.", "gs_paper": "GS Paper 3 (Economy)", "key_facts": ["India's IT sector: contributes ~7.5% of GDP and ~50% of service exports", "Top IT firms: TCS, Infosys, Wipro, HCL Technologies, Tech Mahindra", "Muted Q1 FY27 growth attributed to slower discretionary spending globally", "AI adoption is disrupting traditional IT outsourcing models"], "source": "The Times of India", "day": "2026-07-06", "day_label": "06 Jul"}, {"title": "Drone Delivery Ecosystem Expands in India Amid Regulatory Push for Last-Mile Solutions", "category": "scitech", "category_name": "Science & Technology", "summary": "India's drone delivery sector is witnessing rapid expansion, with multiple startups and logistics companies testing drone-based last-mile delivery in healthcare (medicines, vaccines), e-commerce, and agriculture. The Drone Rules 2021 and the PLI scheme for drones have provided regulatory clarity and financial incentives. The government's 'Drone Shakti' initiative under the Union Budget 2022-23 aims to make India a global drone hub.", "exam_angle": "Drone policy (Drone Rules 2021, PLI for drones, Drone Shakti), DGCA's regulatory role, and drone applications in healthcare and logistics are frequently tested in GS Paper 3 (Sci-Tech).", "gs_paper": "GS Paper 3 (Sci-Tech)", "key_facts": ["Drone Rules 2021 provide regulatory framework for civilian drone operations in India", "PLI Scheme for Drones: approved with Rs 120 crore outlay", "'Drone Shakti' initiative announced in Union Budget 2022-23", "DGCA is the nodal authority for drone regulation in India"], "source": "NDTV", "day": "2026-07-06", "day_label": "06 Jul"}], "categories": [{"id": "polity", "name": "Polity & Governance"}, {"id": "economy", "name": "Economy & Banking"}, {"id": "ir", "name": "International Relations"}, {"id": "environment", "name": "Environment & Ecology"}, {"id": "scitech", "name": "Science & Technology"}, {"id": "schemes", "name": "Govt Schemes & Policies"}, {"id": "defence", "name": "Defence & Security"}, {"id": "reports", "name": "Reports & Indices"}, {"id": "culture", "name": "Art & Culture"}]};